import { test, expect } from '@playwright/test';

test.describe('Notifications Filter by Type', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should filter notifications by type (info, warning, error) and display only matching notifications', async ({ page }) => {
    // Verify initial notification list
    const notificationList = page.getByRole('region', { name: /notifications/i });
    await expect(notificationList).toBeVisible();

    const notificationItems = page.locator('[data-testid="notification-item"]');
    await expect(notificationItems).toHaveCount(3);

    // Verify all notifications are visible
    const notificationCount = await notificationItems.count();
    expect(notificationCount).toBeGreaterThan(0);

    // Click filter button and select 'Info' type
    const filterButton = page.getByRole('button', { name: /filter notifications/i });
    await filterButton.click();

    const infoFilter = page.getByRole('button', { name: /info/i });
    await infoFilter.click();

    // Verify only info notifications are visible
    const infoNotifications = page.locator('[data-testid="notification-item"][data-type="info"]');
    await expect(infoNotifications).toHaveCount(1);

    // Verify warning notifications are not visible
    const warningNotifications = page.locator('[data-testid="notification-item"][data-type="warning"]');
    await expect(warningNotifications).toHaveCount(0);

    // Verify error notifications are not visible
    const errorNotifications = page.locator('[data-testid="notification-item"][data-type="error"]');
    await expect(errorNotifications).toHaveCount(0);

    // Verify notification list has correct count after filtering
    const filteredNotificationCount = await notificationItems.count();
    expect(filteredNotificationCount).toBe(1);

    // Verify notification list contains correct text
    const filteredNotificationText = await notificationItems.first().textContent();
    expect(filteredNotificationText).toContain('Info');
  });

  test('should handle empty notification list after filtering', async ({ page }) => {
    // Verify initial notification list
    const notificationList = page.getByRole('region', { name: /notifications/i });
    await expect(notificationList).toBeVisible();

    // Verify notification items are visible
    const notificationItems = page.locator('[data-testid="notification-item"]');
    await expect(notificationItems).toHaveCount(3);

    // Click filter button and select 'Error' type
    const filterButton = page.getByRole('button', { name: /filter notifications/i });
    await filterButton.click();

    const errorFilter = page.getByRole('button', { name: /error/i });
    await errorFilter.click();

    // Verify no error notifications are visible
    const errorNotifications = page.locator('[data-testid="notification-item"][data-type="error"]');
    await expect(errorNotifications).toHaveCount(0);

    // Verify notification list is empty
    const notificationCount = await notificationItems.count();
    expect(notificationCount).toBe(0);

    // Verify notification list has no text
    const notificationText = await notificationItems.first().textContent();
    expect(notificationText).toBe('');
  });
});
